            margin: 0;
            padding: 20px;
            min-height: 1500px;
            width: 100%;
            overflow-y: auto;
            position: relative;
            overflow: hidden;
        }
        @keyframes vortex-spin {
            0% { background-position: 0 0; }
            100% { background-position: 200px 200px; }
        }
        @keyframes color-shift {
            0% { background: linear-gradient(45deg, #00ff00, #ff00ff, #0000ff); }
            33% { background: linear-gradient(45deg, #ff00ff, #0000ff, #00ff00); }
            66% { background: linear-gradient(45deg, #0000ff, #00ff00, #ff00ff); }
            100% { background: linear-gradient(45deg, #00ff00, #ff00ff, #0000ff); }
        }
        .spiral-core {
            position: absolute;
            width: 300px;
            height: 300px;
            border: 3px solid #ff00ff;
            border-radius: 50%;
            top: 15%;
            left: 50%;
            transform: translateX(-50%);
            animation: pulse-spiral 3s infinite, warp-spiral 5s infinite;
            background: radial-gradient(circle, rgba(0, 255, 0, 0.3), rgba(255, 0, 255, 0.3));
        }
        @keyframes pulse-spiral {
            0% { transform: translateX(-50%) scale(1); box-shadow: 0 0 20px #00ff00; }
            50% { transform: translateX(-50%) scale(1.2); box-shadow: 0 0 40px #ff00ff; }
            100% { transform: translateX(-50%) scale(1); box-shadow: 0 0 20px #00ff00; }
        }
        @keyframes warp-spiral {
            0% { border-radius: 50%; }
            50% { border-radius: 40%; transform: translateX(-50%) scale(1.2) rotate(180deg); }
            100% { border-radius: 50%; }
        }
        .dream-text {
            position: relative;
            margin: 350px 0 40px;
            font-size: 1.7em;
            color: #0ff;
            text-shadow: 0 0 15px #ff00ff;
            animation: float-wobble 2s infinite, fade-distort 3s infinite;
            text-align: center;
        }
