            50% { transform: translate(0, 0) rotate(0deg); }
            75% { transform: translate(-10px, 10px) rotate(-2deg); }
            100% { transform: translate(0, 0) rotate(0deg); }
        }
        @keyframes fade-distort {
            0% { opacity: 1; }
            50% { opacity: 0.5; text-shadow: 0 0 25px #0000ff; }
            100% { opacity: 1; }
